from flask import Flask, request, jsonify
import jwt
import requests
import os

app = Flask(__name__)

# RSA public key used for RS256 verification
RSA_PUBLIC_KEY = os.environ.get('RSA_PUBLIC_KEY', open('/etc/secrets/jwt-public.pem').read())

# JWT configuration
JWT_ALGORITHMS = os.environ.get('JWT_ALGORITHMS', 'RS256,HS256').split(',')
JWT_ISSUER = os.environ.get('JWT_ISSUER', 'https://auth.internal.corp')

# Internal service endpoint for user data
USER_SERVICE_URL = os.environ.get('USER_SERVICE_URL', 'http://user-service.auth-namespace.svc.cluster.local:8080')

def decode_token(token):
    """Decode and verify JWT token.
    Supports multiple algorithms for backward compatibility with legacy clients.
    """
    try:
        # Attempt verification with configured algorithms
        payload = jwt.decode(
            token,
            RSA_PUBLIC_KEY,
            algorithms=JWT_ALGORITHMS,
            issuer=JWT_ISSUER,
            options={"verify_aud": False}
        )
        return payload, None
    except jwt.ExpiredSignatureError:
        return None, "Token expired"
    except jwt.InvalidIssuerError:
        return None, "Invalid issuer"
    except jwt.InvalidTokenError as e:
        return None, f"Invalid token: {str(e)}"

@app.route('/api/profile', methods=['GET'])
def get_profile():
    """Get user profile - requires valid JWT"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    payload, error = decode_token(token)

    if error:
        return jsonify({"error": error}), 401

    user_id = payload.get('sub')
    role = payload.get('role', 'user')

    return jsonify({"user_id": user_id, "role": role, "status": "authenticated"})

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    """Admin endpoint - lists all users by calling internal user service"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    payload, error = decode_token(token)

    if error:
        return jsonify({"error": error}), 401

    if payload.get('role') != 'admin':
        return jsonify({"error": "Insufficient privileges"}), 403

    # Fetch users from internal service
    try:
        resp = requests.get(
            f"{USER_SERVICE_URL}/internal/users",
            headers={"X-Request-ID": request.headers.get('X-Request-ID', '')},
            timeout=5
        )
        return jsonify(resp.json()), resp.status_code
    except requests.RequestException as e:
        return jsonify({"error": "Service unavailable"}), 503

@app.route('/api/admin/promote', methods=['POST'])
def promote_user():
    """Admin endpoint - promote user role"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    payload, error = decode_token(token)

    if error:
        return jsonify({"error": error}), 401

    if payload.get('role') != 'admin':
        return jsonify({"error": "Insufficient privileges"}), 403

    data = request.get_json()
    target_user = data.get('user_id')
    new_role = data.get('role', 'moderator')

    # Call internal user service to update role
    try:
        resp = requests.post(
            f"{USER_SERVICE_URL}/internal/users/{target_user}/role",
            json={"role": new_role},
            headers={"X-Request-ID": request.headers.get('X-Request-ID', '')},
            timeout=5
        )
        return jsonify(resp.json()), resp.status_code
    except requests.RequestException:
        return jsonify({"error": "Service unavailable"}), 503

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy"})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
